// Generated by tools/build_deploy_bundle.py from tools/project_index.template.html.
export default "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Engineering ML project</title><style>\n*{box-sizing:border-box}body{margin:0;background:#eef2f6;color:#172c40;font:17px/1.55 Arial,sans-serif}\nmain{max-width:720px;margin:28px auto;background:#fff;border-radius:14px;overflow:hidden;box-shadow:0 2px 14px rgba(23,44,64,.08)}\nheader{background:#126573;color:#fff;padding:24px 30px 20px}.brand{font-size:13px;letter-spacing:1.5px;font-weight:bold;opacity:.85}\nh1{font-size:27px;line-height:1.2;margin:6px 0 4px}.badge{display:inline-block;background:#edab37;color:#172c40;font-size:13px;font-weight:bold;letter-spacing:.5px;padding:3px 10px;border-radius:20px;vertical-align:middle}\n.facts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:16px 0 0}.facts div{background:rgba(255,255,255,.12);border-radius:8px;padding:8px 12px;font-size:14px;line-height:1.35}.facts b{display:block;font-size:12px;letter-spacing:.8px;opacity:.85;text-transform:uppercase}\n.body{padding:24px 30px 30px}h2{font-size:21px;margin:26px 0 8px}\n.step{border:1px solid #d3dce5;border-radius:10px;padding:16px 18px;margin-top:16px}.step.todo{border:2px solid #edab37;background:#fffaf0}.step.done{border-color:#7fb08c}\n.step legend,.stephead{font-weight:bold;font-size:18px;padding:0 6px;margin-left:-6px}.num{display:inline-block;width:26px;height:26px;border-radius:50%;background:#126573;color:#fff;text-align:center;font-size:15px;line-height:26px;margin-right:8px}\n.step.done .num{background:#1f6b35}.step.bad{border:2px solid #9f251e;background:#fdf1f0}.step.bad .num{background:#9f251e}fieldset{margin:0;min-width:0}fieldset:disabled{opacity:.5}\nlabel{display:block;font-weight:bold;margin-top:14px}input,select{width:100%;padding:12px;border:1px solid #8194a6;border-radius:6px;font:inherit;background:#fff;color:inherit}\nselect{font-size:18px;appearance:none;-webkit-appearance:none;background-image:linear-gradient(45deg,transparent 50%,#126573 50%),linear-gradient(135deg,#126573 50%,transparent 50%);background-position:calc(100% - 22px) 52%,calc(100% - 16px) 52%;background-size:6px 6px;background-repeat:no-repeat;padding-right:44px}\ninput[type=checkbox]{width:22px;height:22px;margin:0 10px 0 0;vertical-align:middle}\nbutton,.go{background:#126573;color:#fff;border:0;border-radius:6px;padding:13px 20px;font:inherit;font-weight:bold;cursor:pointer;text-decoration:none;display:inline-block;margin:10px 6px 6px 0}\nbutton.alt{background:#fff;color:#126573;border:2px solid #126573}button:disabled{opacity:.5;cursor:not-allowed}\n.muted{color:#526577;font-size:15px}.error{color:#9f251e;font-weight:bold}.ok{color:#1f6b35;font-weight:bold}\n.who{border:2px solid #126573;border-radius:8px;padding:10px 14px;margin-top:12px}.warn{border:2px solid #9f251e;background:#fdf1f0;border-radius:8px;padding:10px 14px;margin-top:12px}\n.chosen{margin-top:10px;font-size:15px}.summary{background:#f4f7fa;border-radius:8px;padding:12px 14px;margin-top:18px;font-size:15px}\ninput:focus,select:focus,button:focus,.go:focus{outline:3px solid #edab37;outline-offset:2px}[hidden]{display:none!important}\n@media(max-width:820px){main{margin:0;border-radius:0}header,.body{padding-left:16px;padding-right:16px}h1{font-size:24px}.facts{grid-template-columns:1fr;gap:2px;margin-top:12px}.facts div{background:none;padding:0;font-size:14px}.facts b{display:inline;margin-right:6px}header{padding-top:18px;padding-bottom:16px}.go,#start{display:block;width:100%;text-align:center}}\n</style></head><body><main>\n<header><div class=\"brand\">IUEA ENGINEERING ML PROJECT</div><h1 id=\"heading\">Engineering ML project</h1><span class=\"badge\" id=\"mode\">FINAL PROJECT, MARKED</span>\n<div class=\"facts\"><div><b>Window</b><span id=\"fWindow\">Monday 23 November 2026, 00:00 to Wednesday 25 November 2026, 23:59</span></div><div><b>Your time</b><span id=\"fTime\">3 hours from Start. It cannot be paused.</span></div><div><b>Last full start</b><span id=\"fLast\">Wednesday 25 November 2026, 20:59</span></div></div></header>\n<div class=\"body\">\n<p class=\"muted\">Kampala time. Use a laptop with steady internet, in your normal browser (not inside WhatsApp). Coming back later gives the same notebook and deadline.</p>\n<form id=\"identity\" autocomplete=\"off\">\n<div class=\"step todo\" id=\"courseStep\"><div class=\"stephead\"><span class=\"num\">1</span>Your course</div>\n<label for=\"courseSel\">Choose the course you are registered for</label>\n<select id=\"courseSel\" required aria-describedby=\"courseChosen\"><option value=\"\" selected disabled>Choose your course...</option>\n<option value=\"CML3111\">CML3111: Electrical, Mechatronics, Robotics and Communications (BSEE, BSMRE)</option>\n<option value=\"CML3112\">CML3112: Civil Engineering and Architecture (BSCE, BARC)</option>\n<option value=\"CML3113\">CML3113: Mining and Petroleum Engineering (BSME, BSPE, BPE)</option></select>\n<div id=\"courseChosen\" class=\"chosen muted\" role=\"status\" aria-live=\"polite\">Not chosen yet. The letters near the end of your registration number (for example BSCE in 24/351/BSCE-S) show your programme.</div></div>\n<fieldset class=\"step\" id=\"whoStep\" disabled><legend><span class=\"num\">2</span>Who you are</legend>\n<label for=\"registration\">Registration number</label>\n<input id=\"registration\" required maxlength=\"40\" placeholder=\"for example 24/351/BSCE-S\" aria-describedby=\"regHelp regResult\">\n<div id=\"regHelp\" class=\"muted\">As on your student card.</div>\n<div id=\"regResult\" role=\"status\" aria-live=\"polite\"></div>\n<div id=\"otherCourse\" class=\"warn\" hidden></div>\n<div id=\"whoBox\" class=\"who\" hidden><label for=\"isMe\" style=\"margin:0\"><input type=\"checkbox\" id=\"isMe\">This is me: <span id=\"whoName\"></span></label></div>\n<div id=\"nameBox\" class=\"who\" hidden><label for=\"fullName\" style=\"margin-top:0\">Your full name</label><input id=\"fullName\" maxlength=\"160\" autocomplete=\"name\"><div class=\"muted\">Your number is not on this course's class list yet. You can still start; your lecturer will check it later.</div></div></fieldset>\n<fieldset class=\"step\" id=\"emailStep\" disabled><legend><span class=\"num\">3</span>Your Google account</legend>\n<label for=\"email\">Google account email</label>\n<input id=\"email\" type=\"email\" required maxlength=\"254\" autocomplete=\"email\">\n<label for=\"email2\">Type the same email again</label>\n<input id=\"email2\" type=\"email\" required maxlength=\"254\" autocomplete=\"off\">\n<div id=\"emailHelp\" class=\"muted\">Use the account you are signed into in Colab (top-right of colab.research.google.com). Your notebook is shared with this account only.</div></fieldset>\n<div id=\"summary\" class=\"summary\" hidden></div>\n<button id=\"start\" type=\"submit\" disabled>Start / resume my project</button>\n</form>\n<p id=\"status\" role=\"status\" aria-live=\"polite\"></p>\n<section id=\"ready\" hidden><h2>Your project is ready</h2><a id=\"colab\" class=\"go\" target=\"_blank\" rel=\"noopener\">Open my project in Colab</a>\n<p id=\"timer\" role=\"timer\" aria-live=\"off\" style=\"font-size:34px;font-weight:bold;color:#126573;margin:14px 0\"></p><p id=\"deadline\"></p>\n<div id=\"fixBox\" class=\"who\" hidden><strong>Typed the wrong email?</strong> You can correct it once, in the first 15 minutes, before any work is saved.\n<label for=\"fix1\">Correct Google email</label><input id=\"fix1\" type=\"email\" maxlength=\"254\"><label for=\"fix2\">Type it again</label><input id=\"fix2\" type=\"email\" maxlength=\"254\">\n<button id=\"fixGo\" type=\"button\" disabled>Use this email instead</button><div id=\"fixResult\" role=\"status\" aria-live=\"polite\"></div></div>\n<ol><li>Run <strong>Setup</strong> first. Do not edit it. It shows your time left.</li>\n<li>Work only in this notebook. Press Ctrl+S now and then.</li>\n<li><strong>No Submit button.</strong> <span id=\"endText\">At your deadline, editing stops and your work is collected.</span></li></ol>\n<button id=\"checkWork\" type=\"button\">Check my work</button> <button id=\"finish\" type=\"button\">I have finished</button>\n<div id=\"workResult\" role=\"status\" aria-live=\"polite\"></div>\n<p class=\"muted\"><strong>Check my work:</strong> runs your saved notebook and lists anything missing. No mark is shown.<br><strong>I have finished:</strong> stops editing and collects your work now.<br>Problem? Post a screenshot on the class channel at once.</p></section>\n</div></main><script>\nlet testKey=__TEST_KEY_JSON__;\n// The course is never pre-chosen: the student must pick it, so a wrong link cannot put them on the wrong class list.\nconst assessment=testKey.split('|')[1];let course='';\nconst COURSES={CML3111:'Electrical, Mechatronics, Robotics and Communications',CML3112:'Civil Engineering and Architecture',CML3113:'Mining and Petroleum Engineering'};\nconst courseSel=document.getElementById('courseSel');courseSel.value='';\nfunction setCourse(c){\n course=c;testKey=course+'|'+assessment;courseSel.value=c;\n document.getElementById('courseStep').className='step done';\n document.getElementById('courseChosen').className='chosen ok';\n document.getElementById('courseChosen').textContent='Chosen: '+c+', '+COURSES[c]+'. Wrong course? Change it here before you start.';\n document.getElementById('whoStep').disabled=false;document.getElementById('emailStep').disabled=false;\n document.getElementById('heading').textContent=c+': Engineering ML project';\n reg.dispatchEvent(new Event('input'));\n}\ncourseSel.addEventListener('change',()=>setCourse(courseSel.value));\nconst onGateway=typeof google==='undefined'||!google.script;\nfunction call(route,body,server){\n if(!onGateway)return new Promise((ok,fail)=>{if(!server)return fail(Error('Open the project link from your lecturer to use this.'));google.script.run.withSuccessHandler(ok).withFailureHandler(fail)[server](body);});\n return fetch(route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(r=>r.json()).then(d=>{if(!d.ok)throw Error(d.error||'Try again.');return d.result;});\n}\nconst email2=document.getElementById('email2');\nconst reg=document.getElementById('registration'),email=document.getElementById('email'),isMe=document.getElementById('isMe'),start=document.getElementById('start');\nlet checked='',checkTimer,timerInterval,attempt='',pollTimer;\nconst rehearsal=testKey.endsWith('|ML_REHEARSAL');\nif(rehearsal){document.getElementById('mode').textContent='REHEARSAL, NOT MARKED';document.getElementById('fWindow').textContent='Run by your lecturer in class, until Sunday 22 November 2026. Your project is 23 to 25 November.';document.getElementById('fTime').textContent='A 3-hour practice clock. Nothing is locked or marked.';document.getElementById('fLast').textContent='Any time before the practice closes.';document.title='Engineering ML project rehearsal';}\nconst sameEmail=(a,b)=>a.value.trim()&&a.value.trim().toLowerCase()===b.value.trim().toLowerCase();\nlet onList=true;\nconst fullName=document.getElementById('fullName');\nfunction canStart(){start.disabled=!(course&&checked&&(onList?isMe.checked:fullName.value.trim().length>=3)&&sameEmail(email,email2));\n const sum=document.getElementById('summary');sum.hidden=start.disabled;if(!start.disabled)sum.textContent='You are starting '+course+' ('+COURSES[course]+') as '+checked+', with the Google account '+email.value.trim()+'.';const h=document.getElementById('emailHelp');h.className=email2.value&&!sameEmail(email,email2)?'error':'muted';}\nfunction regFormat(v){return /^\\d{2}\\/[A-Z0-9]{1,8}(\\/[A-Z0-9]{1,8}){1,3}(-[A-Z0-9]{1,4})?$/.test(v.toUpperCase().replace(/\\s+/g,''));}\nreg.addEventListener('input',()=>{\n checked='';isMe.checked=false;document.getElementById('whoBox').hidden=true;document.getElementById('otherCourse').hidden=true;\n if(course&&document.getElementById('courseStep').className==='step bad'){document.getElementById('courseStep').className='step done';const cc=document.getElementById('courseChosen');cc.className='chosen ok';cc.textContent='Chosen: '+course+', '+COURSES[course]+'. Wrong course? Change it here before you start.';}document.getElementById('nameBox').hidden=true;canStart();\n const out=document.getElementById('regResult'),v=reg.value.trim();clearTimeout(checkTimer);out.className='muted';\n if(!v||!course){out.textContent='';return;}\n if(!regFormat(v)){out.textContent='Keep typing. A registration number looks like 24/351/BSCE-S or 23/UG/181/BSCE-J.';}\n else if(PROGRAMMES[programmeOf(v)]&&PROGRAMMES[programmeOf(v)]!==course){const right=PROGRAMMES[programmeOf(v)];showSwitch(right,programmeOf(v)+' students take '+right+', not '+course+'. Choose '+right+' as your course.');return;}\n else out.textContent='Checking the '+course+' class list...';\n checkTimer=setTimeout(()=>{\n  const keyAtCall=testKey;call('/api/check',{test:testKey,registration:v},'portalCheckRegistration').then(r=>{if(reg.value.trim()!==v||testKey!==keyAtCall)return;checked=r.registration;onList=r.onList!==false;out.className='ok';\n   if(onList){out.textContent='Found on the '+course+' class list.';document.getElementById('whoName').textContent=r.nameHint;document.getElementById('whoBox').hidden=false;}\n   else{out.className='muted';out.textContent='Not on the '+course+' class list. Type your full name below to start.';document.getElementById('nameBox').hidden=false;}\n   canStart();})\n  .catch(e=>{if(reg.value.trim()!==v||testKey!==keyAtCall)return;const m=/Choose (CML311[123]) as your course/.exec(e.message);if(m){showSwitch(m[1],e.message);return;}out.className='error';out.textContent=e.message;});\n },regFormat(v)?400:1500);\n});\n// Wrong course: say so plainly and offer the right one. Start stays locked until the course matches.\nconst PROGRAMMES={BSEE:'CML3111',BSMRE:'CML3111',BSCE:'CML3112',BARC:'CML3112',BSME:'CML3113',BSPE:'CML3113',BPE:'CML3113'};\nfunction programmeOf(v){const parts=v.toUpperCase().replace(/\\s+/g,'').split('/');return parts[parts.length-1].replace(/-.*$/,'');}\nfunction showSwitch(right,text){\n const box=document.getElementById('otherCourse');box.textContent='';\n const p=document.createElement('p');p.style.margin='0 0 6px';const s=document.createElement('strong');s.textContent=text;p.append(s);box.append(p);\n if(right&&COURSES[right]){const b=document.createElement('button');b.type='button';b.className='alt';b.textContent='Switch to '+right+' ('+COURSES[right]+')';b.addEventListener('click',()=>setCourse(right));box.append(b);}\n box.hidden=false;document.getElementById('regResult').textContent='';\n document.getElementById('courseStep').className='step bad';const cc=document.getElementById('courseChosen');cc.className='chosen error';cc.textContent='Wrong course for this registration number. Choose '+(right||'the right course')+'.';\n}\nisMe.addEventListener('change',canStart);fullName.addEventListener('input',canStart);email.addEventListener('input',canStart);email2.addEventListener('input',canStart);\ndocument.getElementById('identity').addEventListener('submit',e=>{\n e.preventDefault();const status=document.getElementById('status');start.disabled=true;status.className='';status.textContent='Preparing your notebook...';\n call('/api/files',{test:testKey,name:onList?'(class list)':fullName.value.trim(),email:email.value.trim(),registration:checked},'requestTestFiles').then(r=>{\n  status.textContent=r.resumed?'Welcome back. Your timer is still running from your first start.':'Your 3 hours have started.';\n  const link=document.getElementById('colab');link.href=r.colabUrl;link.textContent=r.resumed?'Resume my project in Colab':'Open my project in Colab';\n  document.getElementById('deadline').textContent=(rehearsal?'Practice deadline (nothing is locked): ':'Your deadline: ')+r.deadline+'.';document.getElementById('ready').hidden=false;\n  attempt=r.attempt||'';if(rehearsal)document.getElementById('endText').textContent='Rehearsal: nothing is locked or marked. Practise Check my work and I have finished.';\n  showStatus();\n  const offset=Date.parse(r.serverNow)-Date.now();clearInterval(timerInterval);\n  const tick=()=>{const left=Math.max(0,Date.parse(r.personalDeadline)-(Date.now()+offset)),s=Math.ceil(left/1000);document.getElementById('timer').textContent=left?'Time left: '+Math.floor(s/3600)+'h '+Math.floor(s%3600/60)+'m '+s%60+'s.':'Your time has ended. Nothing submitted now is marked.';};\n  tick();timerInterval=setInterval(tick,1000);start.disabled=false;\n  const fix=document.getElementById('fixBox');fix.hidden=!(r.startedAt&&Date.now()+offset-Date.parse(r.startedAt)<15*60000);\n }).catch(err=>{status.className='error';status.textContent=err.message||'Could not prepare your notebook. Tell your lecturer.';canStart();});\n});\nfunction render(r){\n const out=document.getElementById('workResult');out.className='';out.textContent='';\n const lines=[];\n if(r.state==='collected')lines.push('Your work was collected: '+r.collected.source+', saved '+r.collected.time+' (Kampala time).'+(rehearsal?'':' Editing has stopped.'));\n else if(r.last_backup)lines.push('Last automatic backup received '+r.last_backup+' (Kampala time).');\n if(r.checks){lines.push('Checked '+r.checks.checked+': runs from the top: '+(r.checks.runs_from_top?'yes':'no, first cell that stopped: '+r.checks.first_failed_cell)+'.');\n  lines.push('Required results found: '+(r.checks.missing_functions.length?'missing '+r.checks.missing_functions.join(', '):'all of them')+'. MEMO form found: '+(r.checks.memo_found?'yes':'no')+'.');\n  if(!r.checks.issued_file)lines.push('This was not the notebook issued to you. Click Resume and work in the issued notebook.');}\n if(r.pending)lines.push('A check is running. This page updates by itself.');\n if(!rehearsal)lines.push(r.mark?'Mark: '+r.mark+'.':'Marks are shown after the window closes and the lecturer releases them.');\n lines.forEach(t=>{const p=document.createElement('p');p.textContent=t;out.appendChild(p);});\n document.getElementById('finish').disabled=r.state==='collected'&&!rehearsal;\n clearTimeout(pollTimer);if(r.pending)pollTimer=setTimeout(showStatus,15000);\n}\nfunction showStatus(){if(!attempt)return;call('/api/status',{attempt}).then(render).catch(()=>{});}\ndocument.getElementById('checkWork').addEventListener('click',()=>{\n const out=document.getElementById('workResult');out.className='';out.textContent='Sending your saved notebook for checking...';\n call('/api/mywork',{attempt}).then(r=>{out.textContent='Checking the version saved '+r.checked_version+'. The result appears here in one to three minutes.';pollTimer=setTimeout(showStatus,15000);})\n .catch(e=>{out.className='error';out.textContent=e.message;showStatus();});\n});\ndocument.getElementById('finish').addEventListener('click',()=>{\n if(!confirm(rehearsal?'Practise finishing? In the rehearsal you can keep working afterwards.':'I have finished: your editing stops now and your work is collected. You cannot continue. Are you sure?'))return;\n const out=document.getElementById('workResult');out.className='';out.textContent='Collecting your work...';\n call('/api/finish',{attempt}).then(render).catch(e=>{out.className='error';out.textContent=e.message;});\n});\nconst fix1=document.getElementById('fix1'),fix2=document.getElementById('fix2'),fixGo=document.getElementById('fixGo');\n[fix1,fix2].forEach(x=>x.addEventListener('input',()=>{fixGo.disabled=!sameEmail(fix1,fix2);}));\nfixGo.addEventListener('click',()=>{\n const out=document.getElementById('fixResult');out.className='';out.textContent='Sharing a new notebook with '+fix1.value.trim()+'...';fixGo.disabled=true;\n call('/api/fixemail',{attempt,new_email:fix1.value.trim()}).then(r=>{\n  const link=document.getElementById('colab');link.href=r.colabUrl;out.className='ok';\n  out.textContent='Done. Open my project in Colab now opens a new notebook shared with '+r.email+'. The old notebook is no longer shared. Your deadline is the same.';\n  email.value=email2.value=r.email;document.getElementById('fixBox').querySelectorAll('input,button').forEach(x=>x.disabled=true);\n }).catch(e=>{out.className='error';out.textContent=e.message;fixGo.disabled=false;});\n});\n</script></body></html>\n";
